import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface ExpenseItem {
  description: string;
  value: number;
}

export interface IncomeItem {
  description: string;
  value: number;
}

export enum HealthStatus {
  HEALTHY = 'Saudável',
  ATTENTION = 'Atenção',
  CRITICAL = 'Crítico'
}

export interface FinanceAnalysis {
  houseExpenses: ExpenseItem[];
  monthlyFixedExpenses: ExpenseItem[];
  workIncome: IncomeItem[];
  thirdPartyIncome: IncomeItem[];
  summary: {
    totalWorkIncome: number;
    totalExpenses: number;
    remainingBalance: number;
    compromisePercentage: number;
    status: HealthStatus;
    alertMessage: string | null;
  };
  analysisDate: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { FinanceAnalysis, HealthStatus } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_INSTRUCTION = `
Você é o "Master Finance", um assistente especializado em gestão de fluxo de caixa pessoal. 
Sua função é processar entradas de texto natural e organizar as finanças do usuário em uma estrutura rígida e limpa.

1. Organização de Categorias:
- 🏠 Contas da Casa: (Ex: Aluguel, água, luz, internet).
- 📅 Contas Mensais/Fixas: (Ex: Impostos, contabilidade, carro, celular).
- 📥 Entradas (Trabalho): Salários e rendas fixas.
- 💳 Entradas (Terceiros/Cartão): Valores que entram apenas para pagar dívidas de amigos ou compras emprestadas (Não somar como renda disponível).

2. Lógica de Cálculo:
- Gasto Total: Soma das 'Contas da Casa' + 'Contas Mensais'.
- Margem de Segurança: Percentual de comprometimento (Gasto Total / Salário de Trabalho).
- Regra dos 80%: Se o Gasto Total for > 80% do Salário, adicione um alerta em alertMessage.

3. Saúde Financeira:
- Verde (Healthy): Comprometimento <= 50%
- Amarelo (Attention): Comprometimento > 50% e <= 80%
- Vermelho (Critical): Comprometimento > 80%

Extraia os dados no formato JSON especificado. Use 0 se não encontrar dados para alguma categoria.
`;

export async function analyzeFinance(input: string): Promise<FinanceAnalysis> {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Analise as seguintes movimentações financeiras: ${input}`,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          houseExpenses: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                description: { type: Type.STRING },
                value: { type: Type.NUMBER }
              },
              required: ["description", "value"]
            }
          },
          monthlyFixedExpenses: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                description: { type: Type.STRING },
                value: { type: Type.NUMBER }
              },
              required: ["description", "value"]
            }
          },
          workIncome: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                description: { type: Type.STRING },
                value: { type: Type.NUMBER }
              },
              required: ["description", "value"]
            }
          },
          thirdPartyIncome: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                description: { type: Type.STRING },
                value: { type: Type.NUMBER }
              },
              required: ["description", "value"]
            }
          },
          summary: {
            type: Type.OBJECT,
            properties: {
              totalWorkIncome: { type: Type.NUMBER },
              totalExpenses: { type: Type.NUMBER },
              remainingBalance: { type: Type.NUMBER },
              compromisePercentage: { type: Type.NUMBER },
              status: { type: Type.STRING },
              alertMessage: { type: Type.STRING }
            },
            required: ["totalWorkIncome", "totalExpenses", "remainingBalance", "compromisePercentage", "status"]
          }
        },
        required: ["houseExpenses", "monthlyFixedExpenses", "workIncome", "thirdPartyIncome", "summary"]
      }
    }
  });

  const rawJson = response.text.trim();
  const data = JSON.parse(rawJson);

  return {
    ...data,
    analysisDate: new Date().toLocaleDateString('pt-BR')
  };
}

import React from 'react';

interface SummaryCardProps {
  label: string;
  value: number;
  type?: 'income' | 'expense' | 'balance';
  icon?: React.ReactNode;
}

const SummaryCard: React.FC<SummaryCardProps> = ({ label, value, type = 'balance', icon }) => {
  const getColors = () => {
    switch (type) {
      case 'income': return 'text-emerald-600 bg-emerald-50 border-emerald-100';
      case 'expense': return 'text-rose-600 bg-rose-50 border-rose-100';
      default: return 'text-indigo-600 bg-indigo-50 border-indigo-100';
    }
  };

  const formattedValue = new Intl.NumberFormat('pt-BR', {
    style: 'currency',
    currency: 'BRL',
  }).format(value);

  return (
    <div className={`p-5 rounded-2xl border ${getColors()} transition-all hover:shadow-md`}>
      <div className="flex items-center gap-3 mb-2">
        {icon && <div className="opacity-80">{icon}</div>}
        <span className="text-sm font-medium opacity-80 uppercase tracking-wider">{label}</span>
      </div>
      <div className="text-2xl font-bold">{formattedValue}</div>
    </div>
  );
};

export default SummaryCard;

import React from 'react';
import { ExpenseItem } from '../types';

interface ExpenseTableProps {
  title: string;
  items: ExpenseItem[];
  icon: string;
}

const ExpenseTable: React.FC<ExpenseTableProps> = ({ title, items, icon }) => {
  if (items.length === 0) return null;

  const total = items.reduce((acc, curr) => acc + curr.value, 0);

  return (
    <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm">
      <div className="bg-slate-50 px-6 py-4 border-b border-slate-200 flex justify-between items-center">
        <h3 className="font-semibold text-slate-700 flex items-center gap-2">
          <span>{icon}</span> {title}
        </h3>
        <span className="text-xs font-bold text-slate-400 uppercase tracking-tighter">
          Total: {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(total)}
        </span>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full text-left text-sm">
          <thead>
            <tr className="border-b border-slate-100 text-slate-400 uppercase text-[10px] tracking-widest font-bold">
              <th className="px-6 py-3">Descrição</th>
              <th className="px-6 py-3 text-right">Valor</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {items.map((item, idx) => (
              <tr key={idx} className="hover:bg-slate-50/50 transition-colors">
                <td className="px-6 py-4 text-slate-600 font-medium">{item.description}</td>
                <td className="px-6 py-4 text-right text-slate-900 font-semibold">
                  {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(item.value)}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default ExpenseTable;

