};

export default ExpenseTable;

import React, { useState } from 'react';
import { 
  FileSpreadsheet, 
  TrendingUp, 
  TrendingDown, 
  CreditCard, 
  Home, 
  Calendar,
  AlertTriangle, 
  CheckCircle2,
  Import,
  Calculator,
  Briefcase
} from 'lucide-react';
import { FinanceAnalysis, HealthStatus } from './types';
import { analyzeFinance } from './services/geminiService';
import ExpenseTable from './components/ExpenseTable';

const App: React.FC = () => {
  const [input, setInput] = useState('');
  const [analysis, setAnalysis] = useState<FinanceAnalysis | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleAnalyze = async () => {
    if (!input.trim()) return;
    setLoading(true);
    setError(null);
    try {
      const result = await analyzeFinance(input);
      setAnalysis(result);
    } catch (err: any) {
      console.error(err);
      setError('Falha ao processar os dados. Verifique sua entrada.');
    } finally {
      setLoading(false);
    }
  };

  const getStatusStyle = (status: HealthStatus) => {
    switch (status) {
