import { GoogleGenAI, Type } from "@google/genai";
import { FinanceAnalysis, FinanceItem } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_INSTRUCTION = `
Você é o "Master Finance", assistente de gestão de fluxo de caixa.
Sua função é analisar uma lista de itens financeiros e gerar um Resumo Executivo e Status de Saúde.

LOGICA DE CÁLCULO:
1. Gasto Total = Soma de 'house' (Casa) + 'fixed' (Mensais).
2. Entradas (Trabalho) = Categoria 'work'.
3. Entradas (Terceiros) = Categoria 'thirdParty'. Estas NÃO somam na renda disponível, são apenas compensações.
4. Compromisso = Gasto Total / Entradas (Trabalho).
5. ALERTA: Se Gasto Total > 80% das Entradas (Trabalho), obrigatoriamente gere um alerta em alertMessage: "⚠️ ALERTA DE RISCO: Orçamento comprometido acima de 80%!".

STATUS:
- Verde (Healthy): Comprometimento <= 50%
- Amarelo (Attention): Comprometimento > 50% e <= 80%
- Vermelho (Critical): Comprometimento > 80%

RETORNE APENAS JSON.
`;

export async function analyzeFinanceData(items: FinanceItem[]): Promise<FinanceAnalysis> {
  const prompt = `Analise estes dados financeiros estruturados e gere o resumo: ${JSON.stringify(items)}`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          summary: {
            type: Type.OBJECT,
            properties: {
              totalWorkIncome: { type: Type.NUMBER },
              totalExpenses: { type: Type.NUMBER },
              remainingBalance: { type: Type.NUMBER },
              compromisePercentage: { type: Type.NUMBER },
              status: { type: Type.STRING },
              alertMessage: { type: Type.STRING, nullable: true }
            },
            required: ["totalWorkIncome", "totalExpenses", "remainingBalance", "compromisePercentage", "status"]
          }
        },
        required: ["summary"]
      }
    }
  });

  const data = JSON.parse(response.text.trim());
  return {
    ...data,
    analysisDate: new Date().toLocaleDateString('pt-BR')
  };
}

