interface ExpenseTableProps {
  title: string;
  items: FinanceItem[];
  icon: string;
  type: 'income' | 'expense' | 'neutral';
  onRemove: (id: string) => void;
  onUpdate: (id: string, updates: Partial<FinanceItem>) => void;
}

const ExpenseTable: React.FC<ExpenseTableProps> = ({ title, items, icon, type, onRemove, onUpdate }) => {
  const total = items.reduce((acc, curr) => acc + curr.value, 0);

  const fmt = (val: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const handleValueChange = (id: string, rawValue: string) => {
    const digits = rawValue.replace(/\D/g, '');
    const numericValue = digits ? parseInt(digits) / 100 : 0;
    onUpdate(id, { value: numericValue });
  };

  const showStatus = type === 'expense';

  return (
    <div className="bg-white border border-slate-200 shadow-sm overflow-hidden mb-6">
      <div className="bg-slate-50 px-4 py-2 border-b border-slate-200 flex justify-between items-center">
        <h3 className="text-[11px] font-black text-slate-700 flex items-center gap-2 uppercase tracking-widest">
          <span>{icon}</span> {title}
        </h3>
        <span className={`text-xs font-mono font-bold ${type === 'expense' ? 'text-rose-600' : 'text-emerald-600'}`}>
          TOTAL: {fmt(total)}
        </span>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full text-[11px] font-mono border-collapse">
          <thead>
            <tr className="bg-slate-50/50 border-b border-slate-200 text-slate-400">
