              <th className="px-4 py-2 text-left font-bold border-r border-slate-100">DESCRIÇÃO</th>
              <th className="px-4 py-2 text-center font-bold border-r border-slate-100 w-32">PARCELAS (P / T)</th>
              <th className="px-4 py-2 text-right font-bold w-32">VALOR</th>
              <th className="px-2 py-2 w-10"></th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {items.length > 0 ? (
              items.map((item) => (
                <tr key={item.id} className={`hover:bg-blue-50/30 transition-colors group ${item.status === 'paid' && showStatus ? 'bg-emerald-50/10' : ''}`}>
                  {showStatus && (
                    <td className="px-4 py-2 border-r border-slate-100">
                      <select 
                        value={item.status} 
                        onChange={(e) => onUpdate(item.id, { status: e.target.value as 'pending' | 'paid' })}
                        className={`w-full bg-transparent border-none text-[10px] font-bold uppercase focus:ring-0 cursor-pointer ${item.status === 'paid' ? 'text-emerald-600' : 'text-amber-600'}`}
