                        <option value="paid">Paga</option>
                      </select>
                    </td>
                  )}
                  <td className="px-2 py-1 border-r border-slate-100">
                    <input 
                      type="text"
                      value={item.description}
                      onChange={(e) => onUpdate(item.id, { description: e.target.value })}
                      className={`w-full bg-transparent px-2 py-1 outline-none uppercase text-slate-600 focus:bg-white focus:shadow-inner ${item.status === 'paid' && showStatus ? 'line-through opacity-50' : ''}`}
                    />
                  </td>
                  <td className="px-2 py-1 text-center border-r border-slate-100">
                    <div className="flex items-center justify-center gap-1">
                      <input 
                        type="number"
                        min="0"
                        value={item.paidInstallments}
                        onChange={(e) => onUpdate(item.id, { paidInstallments: parseInt(e.target.value) || 0 })}
                        className="w-10 bg-slate-100 rounded text-center py-0.5 font-bold text-slate-500 outline-none focus:bg-blue-100"
                      />
                      <span className="text-slate-300">/</span>
                      <input 
                        type="number"
                        min="1"
                        value={item.totalInstallments}
                        onChange={(e) => onUpdate(item.id, { totalInstallments: parseInt(e.target.value) || 1 })}
                        className="w-10 bg-slate-100 rounded text-center py-0.5 font-bold text-slate-500 outline-none focus:bg-blue-100"
                      />
                    </div>
                  </td>
                  <td className="px-2 py-1 text-right border-l border-slate-100">
                    <input 
                      type="text"
                      value={fmt(item.value)}
                      onChange={(e) => handleValueChange(item.id, e.target.value)}
                      className={`w-full bg-transparent text-right px-2 py-1 font-bold outline-none focus:bg-white focus:shadow-inner ${type === 'expense' ? 'text-rose-500' : 'text-emerald-600'}`}
                    />
                  </td>
                  <td className="px-2 py-1 text-center">
                    <button 
                      onClick={() => onRemove(item.id)}
                      className="text-slate-300 hover:text-rose-500 transition-colors text-lg"
                    >
                      ×
                    </button>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={showStatus ? 5 : 4} className="px-4 py-8 text-center text-slate-300 italic uppercase tracking-widest text-[9px]">
                  Nenhum registro encontrado
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

