import React, { useState, useMemo } from 'react';
import { 
  Plus,
  AlertTriangle, 
  Calculator,
  LayoutGrid,
  History,
  CheckCircle2,
  Clock,
  FileSpreadsheet,
  Copy,
  Trash2,
  Edit2
} from 'lucide-react';
import { FinanceAnalysis, FinanceItem, HealthStatus, Ledger } from './types';
import { analyzeFinanceData } from './services/geminiService';
import ExpenseTable from './components/ExpenseTable';

const App: React.FC = () => {
  // Initial Ledger
  const initialLedger: Ledger = {
    id: 'default',
    name: 'Janeiro/2025',
    items: []
  };

  const [ledgers, setLedgers] = useState<Ledger[]>([initialLedger]);
  const [activeLedgerId, setActiveLedgerId] = useState<string>('default');
  const [analysis, setAnalysis] = useState<FinanceAnalysis | null>(null);
  const [loading, setLoading] = useState(false);

  // Current active ledger helper
  const activeLedger = useMemo(() => ledgers.find(l => l.id === activeLedgerId) || ledgers[0], [ledgers, activeLedgerId]);
  const items = activeLedger.items;

  // Form State
  const [desc, setDesc] = useState('');
  const [val, setVal] = useState('');
  const [paidCount, setPaidCount] = useState('');
  const [totalCount, setTotalCount] = useState('');
  const [cat, setCat] = useState<'house' | 'fixed' | 'work' | 'thirdParty'>('house');

  const formatCurrencyInput = (value: string) => {
    const digits = value.replace(/\D/g, '');
    if (!digits) return '';
    const amount = parseInt(digits) / 100;
    return new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL',
    }).format(amount);
  };

  const parseCurrencyToNumber = (formattedValue: string) => {
    return parseFloat(formattedValue.replace(/[^\d,]/g, '').replace(',', '.')) || 0;
  };

  const handleValueChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setVal(formatCurrencyInput(e.target.value));
  };

  const addItem = () => {
    const numericValue = parseCurrencyToNumber(val);
    if (!desc || numericValue <= 0) return;

    const newItem: FinanceItem = {
      id: Math.random().toString(36).substr(2, 9),
      description: desc,
      value: numericValue,
      paidInstallments: paidCount ? parseInt(paidCount) : undefined,
      totalInstallments: totalCount ? parseInt(totalCount) : undefined,
      category: cat,
      status: 'pending'
    };

    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: [...l.items, newItem] } : l));

    setDesc('');
    setVal('');
    setPaidCount('');
    setTotalCount('');
  };

  const removeItem = (id: string) => {
    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: l.items.filter(i => i.id !== id) } : l));
  };

  const updateItem = (id: string, updates: Partial<FinanceItem>) => {
    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: l.items.map(i => i.id === id ? { ...i, ...updates } : i) } : l));
  };

  const duplicateLedger = () => {
    // Logic: 
    // 1. Keep items where paid < total
    // 2. For kept items: paid = paid + 1
    // 3. Remove all other items (finished or one-off)
    // 4. Reset status to pending

    const newItems: FinanceItem[] = activeLedger.items
      .filter(item => {
        // If installments are defined and it's not finished
        if (item.paidInstallments !== undefined && item.totalInstallments !== undefined) {
          return item.paidInstallments < item.totalInstallments;
        }
        // User said: "As contas em que não houver parcelas em aberto, deverão ser removidas"
        // Interpretation: If no open installments, it is NOT recurring by default.
        return false;
      })
      .map(item => ({
        ...item,
        id: Math.random().toString(36).substr(2, 9),
        paidInstallments: (item.paidInstallments || 0) + 1,
        status: 'pending'
      }));

    const newLedger: Ledger = {
      id: Math.random().toString(36).substr(2, 9),
      name: `Cópia de ${activeLedger.name}`,
      items: newItems
    };

    setLedgers(prev => [...prev, newLedger]);
    setActiveLedgerId(newLedger.id);
    setAnalysis(null);
  };

  const renameLedger = (id: string) => {
    const newName = prompt('Novo nome para este período:', ledgers.find(l => l.id === id)?.name);
    if (newName) {
      setLedgers(prev => prev.map(l => l.id === id ? { ...l, name: newName } : l));
    }
  };

  const deleteLedger = (id: string) => {
    if (ledgers.length === 1) return alert('Você deve ter pelo menos uma planilha.');
    if (confirm('Deseja excluir este período permanentemente?')) {
      const remaining = ledgers.filter(l => l.id !== id);
      setLedgers(remaining);
      setActiveLedgerId(remaining[0].id);
    }
  };

  const runAnalysis = async () => {
    if (items.length === 0) return;
    setLoading(true);
    try {
      const result = await analyzeFinanceData(items);
      setAnalysis(result);
    } catch (err) {
      console.error(err);
      alert('Erro na análise da Gestão financeira.');
    } finally {
      setLoading(false);
    }
  };

  const getStatusStyle = (status: HealthStatus) => {
    switch (status) {
      case HealthStatus.HEALTHY: return { bg: 'bg-emerald-50', text: 'text-emerald-700', border: 'border-emerald-200' };
      case HealthStatus.ATTENTION: return { bg: 'bg-amber-50', text: 'text-amber-700', border: 'border-amber-200' };
      case HealthStatus.CRITICAL: return { bg: 'bg-rose-50', text: 'text-rose-700', border: 'border-rose-200' };
      default: return { bg: 'bg-slate-50', text: 'text-slate-700', border: 'border-slate-200' };
    }
  };

  const fmt = (val: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const expenseItems = items.filter(i => i.category === 'house' || i.category === 'fixed');
  const totalPaidAmount = expenseItems.filter(i => i.status === 'paid').reduce((acc, curr) => acc + curr.value, 0);
  const totalPendingAmount = expenseItems.filter(i => i.status === 'pending').reduce((acc, curr) => acc + curr.value, 0);
  const countPaid = expenseItems.filter(i => i.status === 'paid').length;
  const countPending = expenseItems.filter(i => i.status === 'pending').length;

  return (
    <div className="min-h-screen bg-slate-100 font-sans text-slate-900">
      <nav className="bg-slate-900 text-white h-14 flex items-center px-6 sticky top-0 z-50 shadow-md">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-blue-600 rounded flex items-center justify-center font-black text-xs">GF</div>
          <h1 className="text-sm font-bold tracking-tighter uppercase">Gestão financeira <span className="text-blue-400 font-mono text-[10px] ml-2">Ledger v5.0</span></h1>
        </div>
      </nav>

      {/* Tabs System */}
      <div className="bg-white border-b border-slate-200 sticky top-14 z-40 px-6 overflow-x-auto flex items-center gap-1 py-2 no-scrollbar">
        {ledgers.map(l => (
          <div key={l.id} className="group relative flex items-center">
            <button 
              onClick={() => { setActiveLedgerId(l.id); setAnalysis(null); }}
              className={`px-4 py-2 text-[10px] font-bold uppercase tracking-widest whitespace-nowrap transition-all border-b-2 flex items-center gap-2 ${activeLedgerId === l.id ? 'border-blue-600 text-blue-600 bg-blue-50/50' : 'border-transparent text-slate-400 hover:text-slate-600'}`}
            >
              {l.name}
            </button>
            {activeLedgerId === l.id && (
              <div className="flex gap-1 ml-1 pr-2">
                <button onClick={() => renameLedger(l.id)} className="p-1 text-slate-400 hover:text-blue-600"><Edit2 size={12} /></button>
                <button onClick={() => deleteLedger(l.id)} className="p-1 text-slate-400 hover:text-rose-600"><Trash2 size={12} /></button>
              </div>
            )}
          </div>
        ))}
        <button 
          onClick={duplicateLedger}
          className="ml-4 flex items-center gap-2 bg-slate-900 text-white text-[9px] font-black uppercase py-2 px-4 rounded hover:bg-slate-800 transition-all shrink-0"
        >
          <Copy size={12} /> Duplicar Período
        </button>
      </div>

      <main className="max-w-6xl mx-auto p-6 space-y-6">

        <section className="bg-white border border-slate-200 shadow-sm p-5">
          <div className="flex items-center gap-2 mb-4 border-b border-slate-100 pb-2">
            <Plus size={14} className="text-blue-600" />
            <h2 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Novo Lançamento ({activeLedger.name})</h2>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-12 gap-3 items-end">
            <div className="md:col-span-3">
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Categoria</label>
              <select value={cat} onChange={e => setCat(e.target.value as any)} className="w-full bg-slate-50 border border-slate-200 p-2 text-sm outline-none focus:ring-1 focus:ring-blue-500">
                <option value="house">🏠 Contas da Casa</option>
                <option value="fixed">📅 Contas Mensais</option>
                <option value="work">📥 Entradas (Trabalho)</option>
                <option value="thirdParty">💳 Entradas (Terceiros)</option>
              </select>
            </div>
            <div className="md:col-span-3">
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Descrição</label>
              <input value={desc} onChange={e => setDesc(e.target.value)} type="text" className="w-full bg-slate-50 border border-slate-200 p-2 text-sm focus:ring-1 focus:ring-blue-500 outline-none" placeholder="Ex: Aluguel" />
            </div>
            <div className="md:col-span-2">
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Valor</label>
              <input value={val} onChange={handleValueChange} type="text" className="w-full bg-slate-50 border border-slate-200 p-2 text-sm focus:ring-1 focus:ring-blue-500 outline-none font-mono" placeholder="R$ 0,00" />
            </div>
            <div className="md:col-span-1">
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Pagas</label>
              <input value={paidCount} onChange={e => setPaidCount(e.target.value)} type="number" min="0" placeholder="-" className="w-full bg-slate-50 border border-slate-200 p-2 text-sm outline-none font-mono placeholder:text-slate-300" />
            </div>
            <div className="md:col-span-1">
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Totais</label>
              <input value={totalCount} onChange={e => setTotalCount(e.target.value)} type="number" min="1" placeholder="-" className="w-full bg-slate-50 border border-slate-200 p-2 text-sm outline-none font-mono placeholder:text-slate-300" />
            </div>
            <div className="md:col-span-2">
              <button onClick={addItem} className="w-full bg-blue-600 text-white text-[10px] font-bold uppercase py-2.5 hover:bg-blue-700 transition-colors shadow-inner">Lançar Item</button>
            </div>
          </div>
        </section>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
          <div className="lg:col-span-8">
            <ExpenseTable 
              title="Contas da Casa" icon="🏠" type="expense" 
              items={items.filter(i => i.category === 'house')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
            <ExpenseTable 
              title="Contas Mensais / Fixas" icon="📅" type="expense" 
              items={items.filter(i => i.category === 'fixed')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
            <ExpenseTable 
              title="Entradas (Trabalho)" icon="📥" type="income" 
              items={items.filter(i => i.category === 'work')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
            <ExpenseTable 
              title="Entradas (Terceiros / Cartão)" icon="💳" type="neutral" 
              items={items.filter(i => i.category === 'thirdParty')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
          </div>

          <div className="lg:col-span-4 space-y-4 sticky top-32">
            <button 
              onClick={runAnalysis}
              disabled={loading || items.length === 0}
              className="w-full bg-slate-900 text-white font-black py-4 uppercase text-xs tracking-[0.2em] shadow-lg hover:bg-slate-800 disabled:bg-slate-300 transition-all flex items-center justify-center gap-2"
            >
              {loading ? <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Calculator size={18} />}
              Análise do Período
            </button>

            {analysis && (
              <>
                <div className={`p-5 border shadow-sm ${getStatusStyle(analysis.summary.status as HealthStatus).bg} ${getStatusStyle(analysis.summary.status as HealthStatus).border}`}>
                  <span className="text-[10px] font-black uppercase text-slate-400 block mb-1 tracking-tighter">Saúde do Período</span>
                  <div className="flex justify-between items-center">
                    <h3 className={`text-xl font-black uppercase tracking-tight ${getStatusStyle(analysis.summary.status as HealthStatus).text}`}>
                      {analysis.summary.status}
                    </h3>
                    <span className="text-sm font-mono font-bold">
                      {(analysis.summary.compromisePercentage * 100).toFixed(1)}%
                    </span>
                  </div>
                  <div className="mt-2 w-full h-1 bg-slate-200 rounded-full overflow-hidden">
                    <div 
                      className={`h-full transition-all duration-1000 ${analysis.summary.compromisePercentage > 0.8 ? 'bg-rose-500' : analysis.summary.compromisePercentage > 0.5 ? 'bg-amber-500' : 'bg-emerald-500'}`}
                      style={{ width: `${Math.min(analysis.summary.compromisePercentage * 100, 100)}%` }}
                    />
                  </div>
                </div>

                <div className="bg-white border border-slate-200 p-5 space-y-4 shadow-sm">
                  <div className="flex items-center gap-2 border-b border-slate-100 pb-2 mb-2">
                    <History size={14} className="text-slate-400" />
                    <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Resumo {activeLedger.name}</h4>
                  </div>
                  <div className="space-y-3 font-mono text-xs">
                    <div className="flex justify-between items-center">
                      <span className="text-slate-400 uppercase">Receita Líquida</span>
                      <span className="font-bold text-emerald-600">{fmt(analysis.summary.totalWorkIncome)}</span>
                    </div>
                    <div className="flex justify-between items-center">
                      <span className="text-slate-400 uppercase">Gastos Totais</span>
                      <span className="font-bold text-rose-500">{fmt(analysis.summary.totalExpenses)}</span>
                    </div>
                    <div className="pt-3 border-t border-slate-100 flex justify-between items-center text-sm">
                      <span className="font-black text-slate-900 uppercase tracking-tighter">Saldo Remanescente</span>
                      <span className={`font-black ${analysis.summary.remainingBalance >= 0 ? 'text-blue-600' : 'text-rose-600'}`}>
                        {fmt(analysis.summary.remainingBalance)}
                      </span>
                    </div>
                  </div>

                  {analysis.summary.alertMessage && (
                    <div className="mt-4 bg-rose-600 text-white p-3 text-[10px] font-bold uppercase tracking-wider flex gap-2 leading-tight">
                      <AlertTriangle size={14} className="shrink-0" />
                      {analysis.summary.alertMessage}
                    </div>
                  )}
                </div>
              </>
            )}

            <div className="bg-slate-800 text-white p-5 space-y-4 shadow-xl border-t-4 border-blue-500">
               <div className="flex items-center gap-2 border-b border-slate-700 pb-2 mb-2">
                  <FileSpreadsheet size={14} className="text-blue-400" />
                  <h4 className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Status de Pagamentos</h4>
               </div>
               <div className="space-y-4">
                  <div className="flex justify-between items-center">
                    <div className="flex items-center gap-2">
                      <CheckCircle2 size={16} className="text-emerald-400" />
                      <div>
                        <p className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter">Pagas ({countPaid})</p>
                        <p className="text-sm font-mono font-bold text-emerald-400">{fmt(totalPaidAmount)}</p>
                      </div>
                    </div>
                  </div>
                  <div className="flex justify-between items-center">
                    <div className="flex items-center gap-2">
                      <Clock size={16} className="text-amber-400" />
                      <div>
                        <p className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter">Pendentes ({countPending})</p>
                        <p className="text-sm font-mono font-bold text-amber-400">{fmt(totalPendingAmount)}</p>
                      </div>
                    </div>
                  </div>
               </div>
            </div>

            {!analysis && !loading && (
              <div className="bg-slate-200/50 border border-dashed border-slate-300 p-10 text-center rounded-lg">
                <LayoutGrid size={24} className="mx-auto text-slate-300 mb-2" />
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest italic">Nenhuma análise gerada</p>
              </div>
            )}
          </div>
        </div>
      </main>

      <footer className="max-w-6xl mx-auto px-6 py-10 border-t border-slate-200 mt-12 flex justify-between items-center opacity-40">
        <div className="text-[10px] font-black uppercase tracking-widest">© 2025 Gestão financeira ANALYTICS</div>
        <div className="text-[10px] font-mono">ESTRUTURA MULTI-PERÍODO RÍGIDA</div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  Plus,
  AlertTriangle, 
  Calculator,
  LayoutGrid,
  History,
  CheckCircle2,
  Clock,
  FileSpreadsheet,
  Copy,
  Trash2,
  Edit2,
  Check
} from 'lucide-react';
import { FinanceAnalysis, FinanceItem, HealthStatus, Ledger } from './types';
import { analyzeFinanceData } from './services/geminiService';
import ExpenseTable from './components/ExpenseTable';

const App: React.FC = () => {
  // Initial Ledger
  const initialLedger: Ledger = {
    id: 'default',
    name: 'Janeiro/2025',
    items: []
  };

  const [ledgers, setLedgers] = useState<Ledger[]>([initialLedger]);
  const [activeLedgerId, setActiveLedgerId] = useState<string>('default');
  const [analysis, setAnalysis] = useState<FinanceAnalysis | null>(null);
  const [loading, setLoading] = useState(false);

  // State for inline editing of tab names
  const [editingLedgerId, setEditingLedgerId] = useState<string | null>(null);
  const [tempLedgerName, setTempLedgerName] = useState('');
  const editInputRef = useRef<HTMLInputElement>(null);

  // Current active ledger helper
  const activeLedger = useMemo(() => ledgers.find(l => l.id === activeLedgerId) || ledgers[0], [ledgers, activeLedgerId]);
  const items = activeLedger.items;

  // Form State
  const [desc, setDesc] = useState('');
  const [val, setVal] = useState('');
  const [paidCount, setPaidCount] = useState('');
  const [totalCount, setTotalCount] = useState('');
  const [cat, setCat] = useState<'house' | 'fixed' | 'work' | 'thirdParty'>('house');

  useEffect(() => {
    if (editingLedgerId && editInputRef.current) {
      editInputRef.current.focus();
      editInputRef.current.select();
    }
  }, [editingLedgerId]);

  const formatCurrencyInput = (value: string) => {
    const digits = value.replace(/\D/g, '');
    if (!digits) return '';
    const amount = parseInt(digits) / 100;
    return new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL',
    }).format(amount);
  };

  const parseCurrencyToNumber = (formattedValue: string) => {
    return parseFloat(formattedValue.replace(/[^\d,]/g, '').replace(',', '.')) || 0;
  };

  const handleValueChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setVal(formatCurrencyInput(e.target.value));
  };

  const addItem = () => {
    const numericValue = parseCurrencyToNumber(val);
    if (!desc || numericValue <= 0) return;

    const newItem: FinanceItem = {
      id: Math.random().toString(36).substr(2, 9),
      description: desc,
      value: numericValue,
      paidInstallments: paidCount ? parseInt(paidCount) : undefined,
      totalInstallments: totalCount ? parseInt(totalCount) : undefined,
      category: cat,
      status: 'pending'
    };

    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: [...l.items, newItem] } : l));

    setDesc('');
    setVal('');
    setPaidCount('');
    setTotalCount('');
  };

  const removeItem = (id: string) => {
    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: l.items.filter(i => i.id !== id) } : l));
  };

  const updateItem = (id: string, updates: Partial<FinanceItem>) => {
    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: l.items.map(i => i.id === id ? { ...i, ...updates } : i) } : l));
  };

  const duplicateLedger = () => {
    const newItems: FinanceItem[] = activeLedger.items
      .filter(item => {
        if (item.paidInstallments !== undefined && item.totalInstallments !== undefined) {
          return item.paidInstallments < item.totalInstallments;
        }
        return false;
      })
      .map(item => ({
        ...item,
        id: Math.random().toString(36).substr(2, 9),
        paidInstallments: (item.paidInstallments || 0) + 1,
        status: 'pending'
      }));

    const newLedger: Ledger = {
      id: Math.random().toString(36).substr(2, 9),
      name: `Cópia de ${activeLedger.name}`,
      items: newItems
    };

    setLedgers(prev => [...prev, newLedger]);
    setActiveLedgerId(newLedger.id);
    setAnalysis(null);
  };

  const startRenaming = (l: Ledger) => {
    setEditingLedgerId(l.id);
    setTempLedgerName(l.name);
  };

  const saveLedgerName = () => {
    if (!editingLedgerId) return;
    const finalName = tempLedgerName.trim() || 'Sem nome';
    setLedgers(prev => prev.map(l => l.id === editingLedgerId ? { ...l, name: finalName } : l));
    setEditingLedgerId(null);
  };

  const handleRenameKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') saveLedgerName();
    if (e.key === 'Escape') setEditingLedgerId(null);
  };

  const deleteLedger = (id: string) => {
    if (ledgers.length === 1) return alert('Você deve ter pelo menos uma planilha.');
    if (confirm('Deseja excluir este período permanentemente?')) {
      const remaining = ledgers.filter(l => l.id !== id);
      setLedgers(remaining);
      setActiveLedgerId(remaining[0].id);
    }
  };

  const runAnalysis = async () => {
    if (items.length === 0) return;
    setLoading(true);
    try {
      const result = await analyzeFinanceData(items);
      setAnalysis(result);
    } catch (err) {
      console.error(err);
      alert('Erro na análise da Gestão financeira.');
    } finally {
      setLoading(false);
    }
  };

  const getStatusStyle = (status: HealthStatus) => {
    switch (status) {
      case HealthStatus.HEALTHY: return { bg: 'bg-emerald-50', text: 'text-emerald-700', border: 'border-emerald-200' };
      case HealthStatus.ATTENTION: return { bg: 'bg-amber-50', text: 'text-amber-700', border: 'border-amber-200' };
      case HealthStatus.CRITICAL: return { bg: 'bg-rose-50', text: 'text-rose-700', border: 'border-rose-200' };
      default: return { bg: 'bg-slate-50', text: 'text-slate-700', border: 'border-slate-200' };
    }
  };

  const fmt = (val: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const expenseItems = items.filter(i => i.category === 'house' || i.category === 'fixed');
  const totalPaidAmount = expenseItems.filter(i => i.status === 'paid').reduce((acc, curr) => acc + curr.value, 0);
  const totalPendingAmount = expenseItems.filter(i => i.status === 'pending').reduce((acc, curr) => acc + curr.value, 0);
  const countPaid = expenseItems.filter(i => i.status === 'paid').length;
  const countPending = expenseItems.filter(i => i.status === 'pending').length;

  return (
    <div className="min-h-screen bg-slate-100 font-sans text-slate-900">
      <nav className="bg-slate-900 text-white h-14 flex items-center px-6 sticky top-0 z-50 shadow-md">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-blue-600 rounded flex items-center justify-center font-black text-xs">GF</div>
          <h1 className="text-sm font-bold tracking-tighter uppercase">Gestão financeira <span className="text-blue-400 font-mono text-[10px] ml-2">Ledger v5.1</span></h1>
        </div>
      </nav>

      {/* Tabs System */}
      <div className="bg-white border-b border-slate-200 sticky top-14 z-40 px-6 overflow-x-auto flex items-center gap-1 py-2 no-scrollbar">
        {ledgers.map(l => (
          <div key={l.id} className="group relative flex items-center">
            {editingLedgerId === l.id ? (
              <div className="flex items-center bg-blue-50 border-b-2 border-blue-600 px-2 py-1 gap-1">
                <input 
                  ref={editInputRef}
                  value={tempLedgerName}
                  onChange={(e) => setTempLedgerName(e.target.value)}
                  onKeyDown={handleRenameKeyDown}
                  onBlur={saveLedgerName}
                  className="bg-transparent text-[10px] font-bold uppercase tracking-widest outline-none text-blue-700 w-32"
                />
                <button onMouseDown={(e) => { e.preventDefault(); saveLedgerName(); }} className="text-blue-600">
                  <Check size={12} />
                </button>
              </div>
            ) : (
              <>
                <button 
                  onClick={() => { setActiveLedgerId(l.id); setAnalysis(null); }}
                  className={`px-4 py-2 text-[10px] font-bold uppercase tracking-widest whitespace-nowrap transition-all border-b-2 flex items-center gap-2 ${activeLedgerId === l.id ? 'border-blue-600 text-blue-600 bg-blue-50/50' : 'border-transparent text-slate-400 hover:text-slate-600'}`}
                >
                  {l.name}
                </button>
                {activeLedgerId === l.id && (
                  <div className="flex gap-1 ml-1 pr-2">
                    <button onClick={() => startRenaming(l)} className="p-1 text-slate-400 hover:text-blue-600 transition-colors">
                      <Edit2 size={12} />
                    </button>
                    <button onClick={() => deleteLedger(l.id)} className="p-1 text-slate-400 hover:text-rose-600 transition-colors">
                      <Trash2 size={12} />
                    </button>
                  </div>
                )}
              </>
            )}
          </div>
        ))}
        <button 
          onClick={duplicateLedger}
          className="ml-4 flex items-center gap-2 bg-slate-900 text-white text-[9px] font-black uppercase py-2 px-4 rounded hover:bg-slate-800 transition-all shrink-0"
        >
          <Copy size={12} /> Duplicar Período
        </button>
      </div>

      <main className="max-w-6xl mx-auto p-6 space-y-6">

        <section className="bg-white border border-slate-200 shadow-sm p-5">
          <div className="flex items-center gap-2 mb-4 border-b border-slate-100 pb-2">
            <Plus size={14} className="text-blue-600" />
            <h2 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Novo Lançamento ({activeLedger.name})</h2>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-12 gap-3 items-end">
            <div className="md:col-span-3">
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Categoria</label>
              <select value={cat} onChange={e => setCat(e.target.value as any)} className="w-full bg-slate-50 border border-slate-200 p-2 text-sm outline-none focus:ring-1 focus:ring-blue-500">
                <option value="house">🏠 Contas da Casa</option>
                <option value="fixed">📅 Contas Mensais</option>
                <option value="work">📥 Entradas (Trabalho)</option>
                <option value="thirdParty">💳 Entradas (Terceiros)</option>
              </select>
            </div>
            <div className="md:col-span-3">
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Descrição</label>
              <input value={desc} onChange={e => setDesc(e.target.value)} type="text" className="w-full bg-slate-50 border border-slate-200 p-2 text-sm focus:ring-1 focus:ring-blue-500 outline-none" placeholder="Ex: Aluguel" />
            </div>
            <div className="md:col-span-2">
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Valor</label>
              <input value={val} onChange={handleValueChange} type="text" className="w-full bg-slate-50 border border-slate-200 p-2 text-sm focus:ring-1 focus:ring-blue-500 outline-none font-mono" placeholder="R$ 0,00" />
            </div>
            <div className="md:col-span-1">
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Pagas</label>
              <input value={paidCount} onChange={e => setPaidCount(e.target.value)} type="number" min="0" placeholder="-" className="w-full bg-slate-50 border border-slate-200 p-2 text-sm outline-none font-mono placeholder:text-slate-300" />
            </div>
            <div className="md:col-span-1">
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Totais</label>
              <input value={totalCount} onChange={e => setTotalCount(e.target.value)} type="number" min="1" placeholder="-" className="w-full bg-slate-50 border border-slate-200 p-2 text-sm outline-none font-mono placeholder:text-slate-300" />
            </div>
            <div className="md:col-span-2">
              <button onClick={addItem} className="w-full bg-blue-600 text-white text-[10px] font-bold uppercase py-2.5 hover:bg-blue-700 transition-colors shadow-inner">Lançar Item</button>
            </div>
          </div>
        </section>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
          <div className="lg:col-span-8">
            <ExpenseTable 
              title="Contas da Casa" icon="🏠" type="expense" 
              items={items.filter(i => i.category === 'house')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
            <ExpenseTable 
              title="Contas Mensais / Fixas" icon="📅" type="expense" 
              items={items.filter(i => i.category === 'fixed')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
            <ExpenseTable 
              title="Entradas (Trabalho)" icon="📥" type="income" 
              items={items.filter(i => i.category === 'work')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
            <ExpenseTable 
              title="Entradas (Terceiros / Cartão)" icon="💳" type="neutral" 
              items={items.filter(i => i.category === 'thirdParty')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
          </div>

          <div className="lg:col-span-4 space-y-4 sticky top-32">
            <button 
              onClick={runAnalysis}
              disabled={loading || items.length === 0}
              className="w-full bg-slate-900 text-white font-black py-4 uppercase text-xs tracking-[0.2em] shadow-lg hover:bg-slate-800 disabled:bg-slate-300 transition-all flex items-center justify-center gap-2"
            >
              {loading ? <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Calculator size={18} />}
              Análise do Período
            </button>

            {analysis && (
              <>
                <div className={`p-5 border shadow-sm ${getStatusStyle(analysis.summary.status as HealthStatus).bg} ${getStatusStyle(analysis.summary.status as HealthStatus).border}`}>
                  <span className="text-[10px] font-black uppercase text-slate-400 block mb-1 tracking-tighter">Saúde do Período</span>
                  <div className="flex justify-between items-center">
                    <h3 className={`text-xl font-black uppercase tracking-tight ${getStatusStyle(analysis.summary.status as HealthStatus).text}`}>
                      {analysis.summary.status}
                    </h3>
                    <span className="text-sm font-mono font-bold">
                      {(analysis.summary.compromisePercentage * 100).toFixed(1)}%
                    </span>
                  </div>
                  <div className="mt-2 w-full h-1 bg-slate-200 rounded-full overflow-hidden">
                    <div 
                      className={`h-full transition-all duration-1000 ${analysis.summary.compromisePercentage > 0.8 ? 'bg-rose-500' : analysis.summary.compromisePercentage > 0.5 ? 'bg-amber-500' : 'bg-emerald-500'}`}
                      style={{ width: `${Math.min(analysis.summary.compromisePercentage * 100, 100)}%` }}
                    />
                  </div>
                </div>

                <div className="bg-white border border-slate-200 p-5 space-y-4 shadow-sm">
                  <div className="flex items-center gap-2 border-b border-slate-100 pb-2 mb-2">
                    <History size={14} className="text-slate-400" />
                    <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Resumo {activeLedger.name}</h4>
                  </div>
                  <div className="space-y-3 font-mono text-xs">
                    <div className="flex justify-between items-center">
                      <span className="text-slate-400 uppercase">Receita Líquida</span>
                      <span className="font-bold text-emerald-600">{fmt(analysis.summary.totalWorkIncome)}</span>
                    </div>
                    <div className="flex justify-between items-center">
                      <span className="text-slate-400 uppercase">Gastos Totais</span>
                      <span className="font-bold text-rose-500">{fmt(analysis.summary.totalExpenses)}</span>
                    </div>
                    <div className="pt-3 border-t border-slate-100 flex justify-between items-center text-sm">
                      <span className="font-black text-slate-900 uppercase tracking-tighter">Saldo Remanescente</span>
                      <span className={`font-black ${analysis.summary.remainingBalance >= 0 ? 'text-blue-600' : 'text-rose-600'}`}>
                        {fmt(analysis.summary.remainingBalance)}
                      </span>
                    </div>
                  </div>

                  {analysis.summary.alertMessage && (
                    <div className="mt-4 bg-rose-600 text-white p-3 text-[10px] font-bold uppercase tracking-wider flex gap-2 leading-tight">
                      <AlertTriangle size={14} className="shrink-0" />
                      {analysis.summary.alertMessage}
                    </div>
                  )}
                </div>
              </>
            )}

            <div className="bg-slate-800 text-white p-5 space-y-4 shadow-xl border-t-4 border-blue-500">
               <div className="flex items-center gap-2 border-b border-slate-700 pb-2 mb-2">
                  <FileSpreadsheet size={14} className="text-blue-400" />
                  <h4 className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Status de Pagamentos</h4>
               </div>
               <div className="space-y-4">
                  <div className="flex justify-between items-center">
                    <div className="flex items-center gap-2">
                      <CheckCircle2 size={16} className="text-emerald-400" />
                      <div>
                        <p className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter">Pagas ({countPaid})</p>
                        <p className="text-sm font-mono font-bold text-emerald-400">{fmt(totalPaidAmount)}</p>
                      </div>
                    </div>
                  </div>
                  <div className="flex justify-between items-center">
                    <div className="flex items-center gap-2">
                      <Clock size={16} className="text-amber-400" />
                      <div>
                        <p className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter">Pendentes ({countPending})</p>
                        <p className="text-sm font-mono font-bold text-amber-400">{fmt(totalPendingAmount)}</p>
                      </div>
                    </div>
                  </div>
               </div>
            </div>

            {!analysis && !loading && (
              <div className="bg-slate-200/50 border border-dashed border-slate-300 p-10 text-center rounded-lg">
                <LayoutGrid size={24} className="mx-auto text-slate-300 mb-2" />
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest italic">Nenhuma análise gerada</p>
              </div>
            )}
          </div>
        </div>
      </main>

      <footer className="max-w-6xl mx-auto px-6 py-10 border-t border-slate-200 mt-12 flex justify-between items-center opacity-40">
        <div className="text-[10px] font-black uppercase tracking-widest">© 2025 Gestão financeira ANALYTICS</div>
        <div className="text-[10px] font-mono">ESTRUTURA MULTI-PERÍODO RÍGIDA</div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  Plus,
  AlertTriangle, 
  Calculator,
  LayoutGrid,
  History,
  CheckCircle2,
  Clock,
  FileSpreadsheet,
  Copy,
  Trash2,
  Edit2,
  Check
} from 'lucide-react';
import { FinanceAnalysis, FinanceItem, HealthStatus, Ledger } from './types';
import { analyzeFinanceData } from './services/geminiService';
import ExpenseTable from './components/ExpenseTable';

const App: React.FC = () => {
  // Initial Ledger
  const initialLedger: Ledger = {
    id: 'default',
    name: 'Janeiro/2025',
    items: []
  };

  const [ledgers, setLedgers] = useState<Ledger[]>([initialLedger]);
  const [activeLedgerId, setActiveLedgerId] = useState<string>('default');
  const [analysis, setAnalysis] = useState<FinanceAnalysis | null>(null);
  const [loading, setLoading] = useState(false);

  // State for inline editing of tab names
  const [editingLedgerId, setEditingLedgerId] = useState<string | null>(null);
  const [tempLedgerName, setTempLedgerName] = useState('');
  const editInputRef = useRef<HTMLInputElement>(null);

  // Current active ledger helper
  const activeLedger = useMemo(() => {
    return ledgers.find(l => l.id === activeLedgerId) || ledgers[0] || initialLedger;
  }, [ledgers, activeLedgerId]);

  const items = activeLedger.items;

  // Form State
  const [desc, setDesc] = useState('');
  const [val, setVal] = useState('');
  const [paidCount, setPaidCount] = useState('');
  const [totalCount, setTotalCount] = useState('');
  const [cat, setCat] = useState<'house' | 'fixed' | 'work' | 'thirdParty'>('house');

  useEffect(() => {
    if (editingLedgerId && editInputRef.current) {
      editInputRef.current.focus();
      editInputRef.current.select();
    }
  }, [editingLedgerId]);

  const formatCurrencyInput = (value: string) => {
    const digits = value.replace(/\D/g, '');
    if (!digits) return '';
    const amount = parseInt(digits) / 100;
    return new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL',
    }).format(amount);
  };

  const parseCurrencyToNumber = (formattedValue: string) => {
    return parseFloat(formattedValue.replace(/[^\d,]/g, '').replace(',', '.')) || 0;
  };

  const handleValueChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setVal(formatCurrencyInput(e.target.value));
  };

  const addItem = () => {
    const numericValue = parseCurrencyToNumber(val);
    if (!desc || numericValue <= 0) return;

    const newItem: FinanceItem = {
      id: Math.random().toString(36).substr(2, 9),
      description: desc,
      value: numericValue,
      paidInstallments: paidCount ? parseInt(paidCount) : undefined,
      totalInstallments: totalCount ? parseInt(totalCount) : undefined,
      category: cat,
      status: 'pending'
    };

    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: [...l.items, newItem] } : l));

    setDesc('');
    setVal('');
    setPaidCount('');
    setTotalCount('');
  };

  const removeItem = (id: string) => {
    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: l.items.filter(i => i.id !== id) } : l));
  };

  const updateItem = (id: string, updates: Partial<FinanceItem>) => {
    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: l.items.map(i => i.id === id ? { ...i, ...updates } : i) } : l));
  };

  const duplicateLedger = () => {
    const newItems: FinanceItem[] = activeLedger.items
      .filter(item => {
        if (item.paidInstallments !== undefined && item.totalInstallments !== undefined) {
          return item.paidInstallments < item.totalInstallments;
        }
        return false;
      })
      .map(item => ({
        ...item,
        id: Math.random().toString(36).substr(2, 9),
        paidInstallments: (item.paidInstallments || 0) + 1,
        status: 'pending'
      }));

    const newLedgerId = Math.random().toString(36).substr(2, 9);
    const newLedger: Ledger = {
      id: newLedgerId,
      name: `Cópia de ${activeLedger.name}`,
      items: newItems
    };

    setLedgers(prev => [...prev, newLedger]);
    setActiveLedgerId(newLedgerId);
    setAnalysis(null);
  };

  const startRenaming = (l: Ledger) => {
    setEditingLedgerId(l.id);
    setTempLedgerName(l.name);
  };

  const saveLedgerName = () => {
    if (!editingLedgerId) return;
    const finalName = tempLedgerName.trim() || 'Sem nome';
    setLedgers(prev => prev.map(l => l.id === editingLedgerId ? { ...l, name: finalName } : l));
    setEditingLedgerId(null);
  };

  const handleRenameKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') saveLedgerName();
    if (e.key === 'Escape') setEditingLedgerId(null);
  };

  const deleteLedger = (e: React.MouseEvent, id: string) => {
    e.stopPropagation(); // Evitar disparar o clique da aba

    if (ledgers.length <= 1) {
      alert('Você deve ter pelo menos uma planilha.');
      return;
    }

    if (window.confirm('Deseja excluir este período permanentemente?')) {
      const remaining = ledgers.filter(l => l.id !== id);
      setLedgers(remaining);

      // Se a aba excluída for a ativa, migrar para a primeira disponível
      if (activeLedgerId === id) {
        setActiveLedgerId(remaining[0].id);
      }
      setAnalysis(null);
    }
  };

  const runAnalysis = async () => {
    if (items.length === 0) return;
    setLoading(true);
    try {
      const result = await analyzeFinanceData(items);
      setAnalysis(result);
    } catch (err) {
      console.error(err);
      alert('Erro na análise da Gestão financeira.');
    } finally {
      setLoading(false);
    }
  };

  const getStatusStyle = (status: HealthStatus) => {
    switch (status) {
      case HealthStatus.HEALTHY: return { bg: 'bg-emerald-50', text: 'text-emerald-700', border: 'border-emerald-200' };
      case HealthStatus.ATTENTION: return { bg: 'bg-amber-50', text: 'text-amber-700', border: 'border-amber-200' };
      case HealthStatus.CRITICAL: return { bg: 'bg-rose-50', text: 'text-rose-700', border: 'border-rose-200' };
      default: return { bg: 'bg-slate-50', text: 'text-slate-700', border: 'border-slate-200' };
    }
  };

  const fmt = (val: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const expenseItems = items.filter(i => i.category === 'house' || i.category === 'fixed');
  const totalPaidAmount = expenseItems.filter(i => i.status === 'paid').reduce((acc, curr) => acc + curr.value, 0);
  const totalPendingAmount = expenseItems.filter(i => i.status === 'pending').reduce((acc, curr) => acc + curr.value, 0);
  const countPaid = expenseItems.filter(i => i.status === 'paid').length;
  const countPending = expenseItems.filter(i => i.status === 'pending').length;

  return (
    <div className="min-h-screen bg-slate-100 font-sans text-slate-900">
      <nav className="bg-slate-900 text-white h-14 flex items-center px-6 sticky top-0 z-50 shadow-md">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-blue-600 rounded flex items-center justify-center font-black text-xs">GF</div>
          <h1 className="text-sm font-bold tracking-tighter uppercase">Gestão financeira <span className="text-blue-400 font-mono text-[10px] ml-2">Ledger v5.2</span></h1>
        </div>
      </nav>

      {/* Tabs System */}
      <div className="bg-white border-b border-slate-200 sticky top-14 z-40 px-6 overflow-x-auto flex items-center gap-1 py-2 no-scrollbar">
        {ledgers.map(l => (
          <div key={l.id} className="group relative flex items-center">
            {editingLedgerId === l.id ? (
              <div className="flex items-center bg-blue-50 border-b-2 border-blue-600 px-2 py-1 gap-1">
                <input 
                  ref={editInputRef}
                  value={tempLedgerName}
                  onChange={(e) => setTempLedgerName(e.target.value)}
                  onKeyDown={handleRenameKeyDown}
                  onBlur={saveLedgerName}
                  className="bg-transparent text-[10px] font-bold uppercase tracking-widest outline-none text-blue-700 w-32"
                />
                <button onMouseDown={(e) => { e.preventDefault(); saveLedgerName(); }} className="text-blue-600">
                  <Check size={12} />
                </button>
              </div>
            ) : (
              <>
                <button 
                  onClick={() => { setActiveLedgerId(l.id); setAnalysis(null); }}
                  className={`px-4 py-2 text-[10px] font-bold uppercase tracking-widest whitespace-nowrap transition-all border-b-2 flex items-center gap-2 ${activeLedgerId === l.id ? 'border-blue-600 text-blue-600 bg-blue-50/50' : 'border-transparent text-slate-400 hover:text-slate-600'}`}
                >
                  {l.name}
                </button>
                {activeLedgerId === l.id && (
                  <div className="flex gap-1 ml-1 pr-2">
                    <button 
                      onClick={() => startRenaming(l)} 
                      title="Renomear período"
                      className="p-1 text-slate-400 hover:text-blue-600 transition-colors"
                    >
                      <Edit2 size={12} />
                    </button>
                    <button 
                      onClick={(e) => deleteLedger(e, l.id)} 
                      title="Excluir período"
                      className="p-1 text-slate-400 hover:text-rose-600 transition-colors"
                    >
                      <Trash2 size={12} />
                    </button>
                  </div>
                )}
              </>
            )}
          </div>
        ))}
        <button 
          onClick={duplicateLedger}
          className="ml-4 flex items-center gap-2 bg-slate-900 text-white text-[9px] font-black uppercase py-2 px-4 rounded hover:bg-slate-800 transition-all shrink-0"
        >
          <Copy size={12} /> Duplicar Período
        </button>
      </div>

      <main className="max-w-6xl mx-auto p-6 space-y-6">

        <section className="bg-white border border-slate-200 shadow-sm p-5">
          <div className="flex items-center gap-2 mb-4 border-b border-slate-100 pb-2">
            <Plus size={14} className="text-blue-600" />
            <h2 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Novo Lançamento ({activeLedger.name})</h2>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-12 gap-3 items-end">
            <div className="md:col-span-3">
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Categoria</label>
              <select value={cat} onChange={e => setCat(e.target.value as any)} className="w-full bg-slate-50 border border-slate-200 p-2 text-sm outline-none focus:ring-1 focus:ring-blue-500">
                <option value="house">🏠 Contas da Casa</option>
                <option value="fixed">📅 Contas Mensais</option>
                <option value="work">📥 Entradas (Trabalho)</option>
                <option value="thirdParty">💳 Entradas (Terceiros)</option>
              </select>
            </div>
            <div className="md:col-span-3">
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Descrição</label>
              <input value={desc} onChange={e => setDesc(e.target.value)} type="text" className="w-full bg-slate-50 border border-slate-200 p-2 text-sm focus:ring-1 focus:ring-blue-500 outline-none" placeholder="Ex: Aluguel" />
            </div>
            <div className="md:col-span-2">
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Valor</label>
              <input value={val} onChange={handleValueChange} type="text" className="w-full bg-slate-50 border border-slate-200 p-2 text-sm focus:ring-1 focus:ring-blue-500 outline-none font-mono" placeholder="R$ 0,00" />
            </div>
            <div className="md:col-span-1">
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Pagas</label>
              <input value={paidCount} onChange={e => setPaidCount(e.target.value)} type="number" min="0" placeholder="-" className="w-full bg-slate-50 border border-slate-200 p-2 text-sm outline-none font-mono placeholder:text-slate-300" />
            </div>
            <div className="md:col-span-1">
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Totais</label>
              <input value={totalCount} onChange={e => setTotalCount(e.target.value)} type="number" min="1" placeholder="-" className="w-full bg-slate-50 border border-slate-200 p-2 text-sm outline-none font-mono placeholder:text-slate-300" />
            </div>
            <div className="md:col-span-2">
              <button onClick={addItem} className="w-full bg-blue-600 text-white text-[10px] font-bold uppercase py-2.5 hover:bg-blue-700 transition-colors shadow-inner">Lançar Item</button>
            </div>
          </div>
        </section>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
          <div className="lg:col-span-8">
            <ExpenseTable 
              title="Contas da Casa" icon="🏠" type="expense" 
              items={items.filter(i => i.category === 'house')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
            <ExpenseTable 
              title="Contas Mensais / Fixas" icon="📅" type="expense" 
              items={items.filter(i => i.category === 'fixed')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
            <ExpenseTable 
              title="Entradas (Trabalho)" icon="📥" type="income" 
              items={items.filter(i => i.category === 'work')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
            <ExpenseTable 
              title="Entradas (Terceiros / Cartão)" icon="💳" type="neutral" 
              items={items.filter(i => i.category === 'thirdParty')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
          </div>

          <div className="lg:col-span-4 space-y-4 sticky top-32">
            <button 
              onClick={runAnalysis}
              disabled={loading || items.length === 0}
              className="w-full bg-slate-900 text-white font-black py-4 uppercase text-xs tracking-[0.2em] shadow-lg hover:bg-slate-800 disabled:bg-slate-300 transition-all flex items-center justify-center gap-2"
            >
              {loading ? <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Calculator size={18} />}
              Análise do Período
            </button>

            {analysis && (
              <>
                <div className={`p-5 border shadow-sm ${getStatusStyle(analysis.summary.status as HealthStatus).bg} ${getStatusStyle(analysis.summary.status as HealthStatus).border}`}>
                  <span className="text-[10px] font-black uppercase text-slate-400 block mb-1 tracking-tighter">Saúde do Período</span>
                  <div className="flex justify-between items-center">
                    <h3 className={`text-xl font-black uppercase tracking-tight ${getStatusStyle(analysis.summary.status as HealthStatus).text}`}>
                      {analysis.summary.status}
                    </h3>
                    <span className="text-sm font-mono font-bold">
                      {(analysis.summary.compromisePercentage * 100).toFixed(1)}%
                    </span>
                  </div>
                  <div className="mt-2 w-full h-1 bg-slate-200 rounded-full overflow-hidden">
                    <div 
                      className={`h-full transition-all duration-1000 ${analysis.summary.compromisePercentage > 0.8 ? 'bg-rose-500' : analysis.summary.compromisePercentage > 0.5 ? 'bg-amber-500' : 'bg-emerald-500'}`}
                      style={{ width: `${Math.min(analysis.summary.compromisePercentage * 100, 100)}%` }}
                    />
                  </div>
                </div>

                <div className="bg-white border border-slate-200 p-5 space-y-4 shadow-sm">
                  <div className="flex items-center gap-2 border-b border-slate-100 pb-2 mb-2">
                    <History size={14} className="text-slate-400" />
                    <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Resumo {activeLedger.name}</h4>
                  </div>
                  <div className="space-y-3 font-mono text-xs">
                    <div className="flex justify-between items-center">
                      <span className="text-slate-400 uppercase">Receita Líquida</span>
                      <span className="font-bold text-emerald-600">{fmt(analysis.summary.totalWorkIncome)}</span>
                    </div>
                    <div className="flex justify-between items-center">
                      <span className="text-slate-400 uppercase">Gastos Totais</span>
                      <span className="font-bold text-rose-500">{fmt(analysis.summary.totalExpenses)}</span>
                    </div>
                    <div className="pt-3 border-t border-slate-100 flex justify-between items-center text-sm">
                      <span className="font-black text-slate-900 uppercase tracking-tighter">Saldo Remanescente</span>
                      <span className={`font-black ${analysis.summary.remainingBalance >= 0 ? 'text-blue-600' : 'text-rose-600'}`}>
                        {fmt(analysis.summary.remainingBalance)}
                      </span>
                    </div>
                  </div>

                  {analysis.summary.alertMessage && (
                    <div className="mt-4 bg-rose-600 text-white p-3 text-[10px] font-bold uppercase tracking-wider flex gap-2 leading-tight">
                      <AlertTriangle size={14} className="shrink-0" />
                      {analysis.summary.alertMessage}
                    </div>
                  )}
                </div>
              </>
            )}

            <div className="bg-slate-800 text-white p-5 space-y-4 shadow-xl border-t-4 border-blue-500">
               <div className="flex items-center gap-2 border-b border-slate-700 pb-2 mb-2">
                  <FileSpreadsheet size={14} className="text-blue-400" />
                  <h4 className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Status de Pagamentos</h4>
               </div>
               <div className="space-y-4">
                  <div className="flex justify-between items-center">
                    <div className="flex items-center gap-2">
                      <CheckCircle2 size={16} className="text-emerald-400" />
                      <div>
                        <p className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter">Pagas ({countPaid})</p>
                        <p className="text-sm font-mono font-bold text-emerald-400">{fmt(totalPaidAmount)}</p>
                      </div>
                    </div>
                  </div>
                  <div className="flex justify-between items-center">
                    <div className="flex items-center gap-2">
                      <Clock size={16} className="text-amber-400" />
                      <div>
                        <p className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter">Pendentes ({countPending})</p>
                        <p className="text-sm font-mono font-bold text-amber-400">{fmt(totalPendingAmount)}</p>
                      </div>
                    </div>
                  </div>
               </div>
            </div>

            {!analysis && !loading && (
              <div className="bg-slate-200/50 border border-dashed border-slate-300 p-10 text-center rounded-lg">
                <LayoutGrid size={24} className="mx-auto text-slate-300 mb-2" />
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest italic">Nenhuma análise gerada</p>
              </div>
            )}
          </div>
        </div>
      </main>

      <footer className="max-w-6xl mx-auto px-6 py-10 border-t border-slate-200 mt-12 flex justify-between items-center opacity-40">
        <div className="text-[10px] font-black uppercase tracking-widest">© 2025 Gestão financeira ANALYTICS</div>
        <div className="text-[10px] font-mono">ESTRUTURA MULTI-PERÍODO RÍGIDA</div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  Plus,
  AlertTriangle, 
  Calculator,
  LayoutGrid,
  History,
  CheckCircle2,
  Clock,
  FileSpreadsheet,
  Copy,
  Trash2,
  Edit2,
  Check
} from 'lucide-react';
import { FinanceAnalysis, FinanceItem, HealthStatus, Ledger } from './types';
import { analyzeFinanceData } from './services/geminiService';
import ExpenseTable from './components/ExpenseTable';

const App: React.FC = () => {
  // Initial Ledger
  const initialLedger: Ledger = {
    id: 'default',
    name: 'Janeiro/2025',
    items: []
  };

  const [ledgers, setLedgers] = useState<Ledger[]>([initialLedger]);
  const [activeLedgerId, setActiveLedgerId] = useState<string>('default');
  const [analysis, setAnalysis] = useState<FinanceAnalysis | null>(null);
  const [loading, setLoading] = useState(false);

  // State for inline editing of tab names
  const [editingLedgerId, setEditingLedgerId] = useState<string | null>(null);
  const [tempLedgerName, setTempLedgerName] = useState('');
  const editInputRef = useRef<HTMLInputElement>(null);

  // Current active ledger helper
  const activeLedger = useMemo(() => {
    const found = ledgers.find(l => l.id === activeLedgerId);
    return found || ledgers[0] || initialLedger;
  }, [ledgers, activeLedgerId]);

  const items = activeLedger.items;

  // Form State
  const [desc, setDesc] = useState('');
  const [val, setVal] = useState('');
  const [paidCount, setPaidCount] = useState('');
  const [totalCount, setTotalCount] = useState('');
  const [cat, setCat] = useState<'house' | 'fixed' | 'work' | 'thirdParty'>('house');

  useEffect(() => {
    if (editingLedgerId && editInputRef.current) {
      editInputRef.current.focus();
      editInputRef.current.select();
    }
  }, [editingLedgerId]);

  const formatCurrencyInput = (value: string) => {
    const digits = value.replace(/\D/g, '');
    if (!digits) return '';
    const amount = parseInt(digits) / 100;
    return new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL',
    }).format(amount);
  };

  const parseCurrencyToNumber = (formattedValue: string) => {
    return parseFloat(formattedValue.replace(/[^\d,]/g, '').replace(',', '.')) || 0;
  };

  const handleValueChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setVal(formatCurrencyInput(e.target.value));
  };

  const addItem = () => {
    const numericValue = parseCurrencyToNumber(val);
    if (!desc || numericValue <= 0) return;

    const newItem: FinanceItem = {
      id: Math.random().toString(36).substr(2, 9),
      description: desc,
      value: numericValue,
      paidInstallments: paidCount ? parseInt(paidCount) : undefined,
      totalInstallments: totalCount ? parseInt(totalCount) : undefined,
      category: cat,
      status: 'pending'
    };

    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: [...l.items, newItem] } : l));

    setDesc('');
    setVal('');
    setPaidCount('');
    setTotalCount('');
  };

  const removeItem = (id: string) => {
    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: l.items.filter(i => i.id !== id) } : l));
  };

  const updateItem = (id: string, updates: Partial<FinanceItem>) => {
    setLedgers(prev => prev.map(l => l.id === activeLedgerId ? { ...l, items: l.items.map(i => i.id === id ? { ...i, ...updates } : i) } : l));
  };

  const duplicateLedger = () => {
    const newItems: FinanceItem[] = activeLedger.items
      .filter(item => {
        if (item.paidInstallments !== undefined && item.totalInstallments !== undefined) {
          return item.paidInstallments < item.totalInstallments;
        }
        return false;
      })
      .map(item => ({
        ...item,
        id: Math.random().toString(36).substr(2, 9),
        paidInstallments: (item.paidInstallments || 0) + 1,
        status: 'pending'
      }));

    const newLedgerId = Math.random().toString(36).substr(2, 9);
    const newLedger: Ledger = {
      id: newLedgerId,
      name: `Cópia de ${activeLedger.name}`,
      items: newItems
    };

    setLedgers(prev => [...prev, newLedger]);
    setActiveLedgerId(newLedgerId);
    setAnalysis(null);
  };

  const startRenaming = (l: Ledger) => {
    setEditingLedgerId(l.id);
    setTempLedgerName(l.name);
  };

  const saveLedgerName = () => {
    if (!editingLedgerId) return;
    const finalName = tempLedgerName.trim() || 'Sem nome';
    setLedgers(prev => prev.map(l => l.id === editingLedgerId ? { ...l, name: finalName } : l));
    setEditingLedgerId(null);
  };

  const handleRenameKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') saveLedgerName();
    if (e.key === 'Escape') setEditingLedgerId(null);
  };

  const handleDeleteLedger = (id: string) => {
    if (ledgers.length <= 1) {
      alert('Você deve manter pelo menos um período ativo.');
      return;
    }

    if (window.confirm('Tem certeza que deseja excluir este período permanentemente? Todos os dados serão perdidos.')) {
      setLedgers(prev => {
        const filtered = prev.filter(l => l.id !== id);

        // Se a aba removida era a ativa, mudar para a primeira restante
        if (activeLedgerId === id) {
          setActiveLedgerId(filtered[0].id);
        }

        return filtered;
      });
      setAnalysis(null);
    }
  };

  const runAnalysis = async () => {
    if (items.length === 0) return;
    setLoading(true);
    try {
      const result = await analyzeFinanceData(items);
      setAnalysis(result);
    } catch (err) {
      console.error(err);
      alert('Erro na análise da Gestão financeira.');
    } finally {
      setLoading(false);
    }
  };

  const getStatusStyle = (status: HealthStatus) => {
    switch (status) {
      case HealthStatus.HEALTHY: return { bg: 'bg-emerald-50', text: 'text-emerald-700', border: 'border-emerald-200' };
      case HealthStatus.ATTENTION: return { bg: 'bg-amber-50', text: 'text-amber-700', border: 'border-amber-200' };
      case HealthStatus.CRITICAL: return { bg: 'bg-rose-50', text: 'text-rose-700', border: 'border-rose-200' };
      default: return { bg: 'bg-slate-50', text: 'text-slate-700', border: 'border-slate-200' };
    }
  };

  const fmt = (val: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const expenseItems = items.filter(i => i.category === 'house' || i.category === 'fixed');
  const totalPaidAmount = expenseItems.filter(i => i.status === 'paid').reduce((acc, curr) => acc + curr.value, 0);
  const totalPendingAmount = expenseItems.filter(i => i.status === 'pending').reduce((acc, curr) => acc + curr.value, 0);
  const countPaid = expenseItems.filter(i => i.status === 'paid').length;
  const countPending = expenseItems.filter(i => i.status === 'pending').length;

  return (
    <div className="min-h-screen bg-slate-100 font-sans text-slate-900">
      <nav className="bg-slate-900 text-white h-14 flex items-center px-6 sticky top-0 z-50 shadow-md">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-blue-600 rounded flex items-center justify-center font-black text-xs">GF</div>
          <h1 className="text-sm font-bold tracking-tighter uppercase">Gestão financeira <span className="text-blue-400 font-mono text-[10px] ml-2">Ledger v5.3</span></h1>
        </div>
      </nav>

      {/* Tabs System */}
      <div className="bg-white border-b border-slate-200 sticky top-14 z-40 px-6 overflow-x-auto flex items-center gap-1 py-2 no-scrollbar">
        {ledgers.map(l => (
          <div key={l.id} className="group relative flex items-center">
            {editingLedgerId === l.id ? (
              <div className="flex items-center bg-blue-50 border-b-2 border-blue-600 px-2 py-1 gap-1">
                <input 
                  ref={editInputRef}
                  value={tempLedgerName}
                  onChange={(e) => setTempLedgerName(e.target.value)}
                  onKeyDown={handleRenameKeyDown}
                  onBlur={saveLedgerName}
                  className="bg-transparent text-[10px] font-bold uppercase tracking-widest outline-none text-blue-700 w-32"
                />
                <button onMouseDown={(e) => { e.preventDefault(); saveLedgerName(); }} className="text-blue-600">
                  <Check size={12} />
                </button>
              </div>
            ) : (
              <div className="flex items-center">
                <button 
                  onClick={() => { setActiveLedgerId(l.id); setAnalysis(null); }}
                  className={`px-4 py-2 text-[10px] font-bold uppercase tracking-widest whitespace-nowrap transition-all border-b-2 flex items-center gap-2 ${activeLedgerId === l.id ? 'border-blue-600 text-blue-600 bg-blue-50/50' : 'border-transparent text-slate-400 hover:text-slate-600'}`}
                >
                  {l.name}
                </button>
                {activeLedgerId === l.id && (
                  <div className="flex gap-1 ml-1 pr-2">
                    <button 
                      onClick={() => startRenaming(l)} 
                      title="Renomear"
                      className="p-1 text-slate-400 hover:text-blue-600 transition-colors"
                    >
                      <Edit2 size={12} className="pointer-events-none" />
                    </button>
                    <button 
                      onClick={(e) => { e.stopPropagation(); handleDeleteLedger(l.id); }} 
                      title="Excluir"
                      className="p-1 text-slate-400 hover:text-rose-600 transition-colors"
                    >
                      <Trash2 size={12} className="pointer-events-none" />
                    </button>
                  </div>
                )}
              </div>
            )}
          </div>
        ))}
        <button 
          onClick={duplicateLedger}
          className="ml-4 flex items-center gap-2 bg-slate-900 text-white text-[9px] font-black uppercase py-2 px-4 rounded hover:bg-slate-800 transition-all shrink-0"
        >
          <Copy size={12} className="pointer-events-none" /> Duplicar Período
        </button>
      </div>

      <main className="max-w-6xl mx-auto p-6 space-y-6">

        <section className="bg-white border border-slate-200 shadow-sm p-5">
          <div className="flex items-center gap-2 mb-4 border-b border-slate-100 pb-2">
            <Plus size={14} className="text-blue-600" />
            <h2 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Novo Lançamento ({activeLedger.name})</h2>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-12 gap-3 items-end">
            <div className="md:col-span-3">
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Categoria</label>
              <select value={cat} onChange={e => setCat(e.target.value as any)} className="w-full bg-slate-50 border border-slate-200 p-2 text-sm outline-none focus:ring-1 focus:ring-blue-500">
                <option value="house">🏠 Contas da Casa</option>
                <option value="fixed">📅 Contas Mensais</option>
                <option value="work">📥 Entradas (Trabalho)</option>
                <option value="thirdParty">💳 Entradas (Terceiros)</option>
              </select>
            </div>
            <div className="md:col-span-3">
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Descrição</label>
              <input value={desc} onChange={e => setDesc(e.target.value)} type="text" className="w-full bg-slate-50 border border-slate-200 p-2 text-sm focus:ring-1 focus:ring-blue-500 outline-none" placeholder="Ex: Aluguel" />
            </div>
            <div className="md:col-span-2">
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Valor</label>
              <input value={val} onChange={handleValueChange} type="text" className="w-full bg-slate-50 border border-slate-200 p-2 text-sm focus:ring-1 focus:ring-blue-500 outline-none font-mono" placeholder="R$ 0,00" />
            </div>
            <div className="md:col-span-1">
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Pagas</label>
              <input value={paidCount} onChange={e => setPaidCount(e.target.value)} type="number" min="0" placeholder="-" className="w-full bg-slate-50 border border-slate-200 p-2 text-sm outline-none font-mono placeholder:text-slate-300" />
            </div>
            <div className="md:col-span-1">
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Totais</label>
              <input value={totalCount} onChange={e => setTotalCount(e.target.value)} type="number" min="1" placeholder="-" className="w-full bg-slate-50 border border-slate-200 p-2 text-sm outline-none font-mono placeholder:text-slate-300" />
            </div>
            <div className="md:col-span-2">
              <button onClick={addItem} className="w-full bg-blue-600 text-white text-[10px] font-bold uppercase py-2.5 hover:bg-blue-700 transition-colors shadow-inner">Lançar Item</button>
            </div>
          </div>
        </section>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
          <div className="lg:col-span-8">
            <ExpenseTable 
              title="Contas da Casa" icon="🏠" type="expense" 
              items={items.filter(i => i.category === 'house')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
            <ExpenseTable 
              title="Contas Mensais / Fixas" icon="📅" type="expense" 
              items={items.filter(i => i.category === 'fixed')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
            <ExpenseTable 
              title="Entradas (Trabalho)" icon="📥" type="income" 
              items={items.filter(i => i.category === 'work')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
            <ExpenseTable 
              title="Entradas (Terceiros / Cartão)" icon="💳" type="neutral" 
              items={items.filter(i => i.category === 'thirdParty')} 
              onRemove={removeItem} onUpdate={updateItem}
            />
          </div>

          <div className="lg:col-span-4 space-y-4 sticky top-32">
            <button 
              onClick={runAnalysis}
              disabled={loading || items.length === 0}
              className="w-full bg-slate-900 text-white font-black py-4 uppercase text-xs tracking-[0.2em] shadow-lg hover:bg-slate-800 disabled:bg-slate-300 transition-all flex items-center justify-center gap-2"
            >
              {loading ? <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Calculator size={18} />}
              Análise do Período
            </button>

            {analysis && (
              <>
                <div className={`p-5 border shadow-sm ${getStatusStyle(analysis.summary.status as HealthStatus).bg} ${getStatusStyle(analysis.summary.status as HealthStatus).border}`}>
                  <span className="text-[10px] font-black uppercase text-slate-400 block mb-1 tracking-tighter">Saúde do Período</span>
                  <div className="flex justify-between items-center">
                    <h3 className={`text-xl font-black uppercase tracking-tight ${getStatusStyle(analysis.summary.status as HealthStatus).text}`}>
                      {analysis.summary.status}
                    </h3>
                    <span className="text-sm font-mono font-bold">
                      {(analysis.summary.compromisePercentage * 100).toFixed(1)}%
                    </span>
                  </div>
                  <div className="mt-2 w-full h-1 bg-slate-200 rounded-full overflow-hidden">
                    <div 
                      className={`h-full transition-all duration-1000 ${analysis.summary.compromisePercentage > 0.8 ? 'bg-rose-500' : analysis.summary.compromisePercentage > 0.5 ? 'bg-amber-500' : 'bg-emerald-500'}`}
                      style={{ width: `${Math.min(analysis.summary.compromisePercentage * 100, 100)}%` }}
                    />
                  </div>
                </div>

                <div className="bg-white border border-slate-200 p-5 space-y-4 shadow-sm">
                  <div className="flex items-center gap-2 border-b border-slate-100 pb-2 mb-2">
                    <History size={14} className="text-slate-400" />
                    <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Resumo {activeLedger.name}</h4>
                  </div>
                  <div className="space-y-3 font-mono text-xs">
                    <div className="flex justify-between items-center">
                      <span className="text-slate-400 uppercase">Receita Líquida</span>
                      <span className="font-bold text-emerald-600">{fmt(analysis.summary.totalWorkIncome)}</span>
                    </div>
                    <div className="flex justify-between items-center">
                      <span className="text-slate-400 uppercase">Gastos Totais</span>
                      <span className="font-bold text-rose-500">{fmt(analysis.summary.totalExpenses)}</span>
                    </div>
                    <div className="pt-3 border-t border-slate-100 flex justify-between items-center text-sm">
                      <span className="font-black text-slate-900 uppercase tracking-tighter">Saldo Remanescente</span>
                      <span className={`font-black ${analysis.summary.remainingBalance >= 0 ? 'text-blue-600' : 'text-rose-600'}`}>
                        {fmt(analysis.summary.remainingBalance)}
                      </span>
                    </div>
                  </div>

                  {analysis.summary.alertMessage && (
                    <div className="mt-4 bg-rose-600 text-white p-3 text-[10px] font-bold uppercase tracking-wider flex gap-2 leading-tight">
                      <AlertTriangle size={14} className="shrink-0" />
                      {analysis.summary.alertMessage}
                    </div>
                  )}
                </div>
              </>
            )}

            <div className="bg-slate-800 text-white p-5 space-y-4 shadow-xl border-t-4 border-blue-500">
               <div className="flex items-center gap-2 border-b border-slate-700 pb-2 mb-2">
                  <FileSpreadsheet size={14} className="text-blue-400" />
                  <h4 className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Status de Pagamentos</h4>
               </div>
               <div className="space-y-4">
                  <div className="flex justify-between items-center">
                    <div className="flex items-center gap-2">
                      <CheckCircle2 size={16} className="text-emerald-400" />
                      <div>
                        <p className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter">Pagas ({countPaid})</p>
                        <p className="text-sm font-mono font-bold text-emerald-400">{fmt(totalPaidAmount)}</p>
                      </div>
                    </div>
                  </div>
                  <div className="flex justify-between items-center">
                    <div className="flex items-center gap-2">
                      <Clock size={16} className="text-amber-400" />
                      <div>
                        <p className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter">Pendentes ({countPending})</p>
                        <p className="text-sm font-mono font-bold text-amber-400">{fmt(totalPendingAmount)}</p>
                      </div>
                    </div>
                  </div>
               </div>
            </div>

            {!analysis && !loading && (
              <div className="bg-slate-200/50 border border-dashed border-slate-300 p-10 text-center rounded-lg">
                <LayoutGrid size={24} className="mx-auto text-slate-300 mb-2" />
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest italic">Nenhuma análise gerada</p>
              </div>
            )}
          </div>
        </div>
      </main>

      <footer className="max-w-6xl mx-auto px-6 py-10 border-t border-slate-200 mt-12 flex justify-between items-center opacity-40">
        <div className="text-[10px] font-black uppercase tracking-widest">© 2025 Gestão financeira ANALYTICS</div>
        <div className="text-[10px] font-mono">ESTRUTURA MULTI-PERÍODO RÍGIDA</div>
      </footer>
    </div>
  );
};

export default App;
